// FINEST YAŞAMKENT - VAPI OUTBOUND hazırlık
// Tetik: Bitrix STATUS_ID = UC_5M177N

let lead = {}; try { lead = $('Lead Detayını Çek').first().json.result || {}; } catch(e) {}
let contact = {}; try { contact = $('Kişi Detayını Çek').first().json.result || {}; } catch(e) {}
let webhook = {}; try { webhook = $('Webhook - Finest Form').first().json || {}; } catch(e) {}

const body = webhook.body || {};
const query = webhook.query || {};
const leadId = (lead.ID || body["data[FIELDS][ID]"] || body.id || query.id || "0").toString().replace("LEAD_", "");
if (leadId === '0') return [];

// Aynı lead'in AI sonucu tekrar UC_5M177N'e dönerken yeniden aranmasını engeller.
// 10 dakika sonra manuel olarak yeniden bu statüye alınırsa tekrar aranabilir.
const staticData = $getWorkflowStaticData('global');
staticData.finestVapiCooldown = staticData.finestVapiCooldown || {};
const nowMs = Date.now();
const last = Number(staticData.finestVapiCooldown[leadId] || 0);
if (last && (nowMs - last) < 10 * 60 * 1000) return [];
staticData.finestVapiCooldown[leadId] = nowMs;

function titleCase(s){
  if(!s) return '';
  return String(s).toLocaleLowerCase('tr-TR').split(' ').filter(Boolean)
    .map(w=>w.charAt(0).toLocaleUpperCase('tr-TR')+w.slice(1)).join(' ');
}
function first(v){
  if(!v) return '';
  if(Array.isArray(v)&&v[0]) return v[0].VALUE||v[0].value||'';
  if(typeof v==='object') return v.VALUE||v.value||'';
  return String(v);
}
function phoneTR(raw){
  let x=String(raw||'').replace(/\D/g,'');
  if(x.startsWith('0090')) x=x.slice(2);
  if(x.startsWith('90')&&x.length===12) return {e164:'+'+x,sms:x,valid:true};
  if(x.startsWith('0')&&x.length===11){ x='90'+x.slice(1); return {e164:'+'+x,sms:x,valid:true}; }
  if(x.length===10&&x.startsWith('5')){ x='90'+x; return {e164:'+'+x,sms:x,valid:true}; }
  return {e164:'',sms:x,valid:false};
}
function istanbulVars(){
  const now = new Date();
  const tr = opts => new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',...opts}).format(now);
  return {
    bugunun_tarihi: tr({day:'2-digit',month:'long',year:'numeric',weekday:'long'}),
    bugun_iso: new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(now),
    su_anki_saat: tr({hour:'2-digit',minute:'2-digit',hour12:false})
  };
}

const firstName = titleCase(String(lead.NAME||contact.NAME||body.name||'').trim());
const lastName = titleCase(String(lead.LAST_NAME||contact.LAST_NAME||body.last_name||'').trim());
const fullName = (firstName+' '+lastName).trim();
const rawPhone = first(lead.PHONE) || first(contact.PHONE) || body["data[FIELDS][PHONE][0][VALUE]"] || body.phone || body.PHONE || query.phone || '';
const phone = phoneTR(rawPhone);
const email = first(lead.EMAIL) || first(contact.EMAIL) || body.email || '';
const assignedTo = String(lead.ASSIGNED_BY_ID || '');
const dateVars = istanbulVars();

const dynamicGreeting = firstName
  ? `Merhabalar ${fullName || firstName}, ben iksre Topraktan'dan Aslı. Az önce Finest Yaşamkent projemiz için form doldurmuştunuz, sizi bekletmeden hemen aramak istedim. Müsaitseniz kısaca bilgi vermek isterim.`
  : `Merhabalar, iksre Topraktan'dan Aslı ben. Az önce Finest Yaşamkent projemiz için form doldurmuştunuz, sizi bekletmeden hemen aramak istedim. Kiminle görüşüyorum acaba?`;

return [{json:{
  lead_id: leadId,
  assigned_to: assignedTo,
  first_name: firstName,
  full_name: fullName || '',
  raw_phone: rawPhone,
  sms_phone: phone.sms,
  customer_phone: phone.e164,
  phone_valid: phone.valid,
  phone_error: phone.valid ? '' : `Geçerli telefon bulunamadı. Gelen değer: ${rawPhone||'BOŞ'}`,
  email,
  bugunun_tarihi: dateVars.bugunun_tarihi,
  bugun_iso: dateVars.bugun_iso,
  su_anki_saat: dateVars.su_anki_saat,
  dynamic_greeting: dynamicGreeting,
  start_mode: firstName ? 'confirm_name' : 'ask_name'
}}];

