const body=$json.body||{}, call=body.call||{}, an=call.call_analysis||{}, c=an.custom_analysis_data||{};
const dv=call.retell_llm_dynamic_variables||{};
const leadId=(call.metadata?.lead_id||dv.bitrix_id||'').toString();
const assignedTo=(call.metadata?.assigned_to||dv.assigned_to||'').toString();
const t=(call.transcript||an.call_summary||'').toLocaleLowerCase('tr-TR');
const status=call.call_status||call.disconnection_reason||'';
const sonuc=String(c.arama_sonucu||'').toLowerCase();
const isRandevu = sonuc==='randevu' || (!!c.appointment_date && sonuc!=='olumsuz');
const acmadi = ['no_answer','busy','failed','voicemail','dial_no_answer','dial_busy','dial_failed'].includes(status) || (t.length<20 && !isRandevu);
const tekrarAra = !isRandevu && !acmadi && (sonuc==='musait_degil' || !!c.aranacak_saat);
const wantsWhatsapp = c.link_istegi===true || t.includes('whatsapp');
let r={ lead_id:leadId, assigned_to:assignedTo, customer_name: dv.user_name||c.extracted_name||'Müşteri', customer_phone: dv.customer_phone||call.to_number||'', call_summary: an.call_summary||'Özet yok.', appointment_date: c.appointment_date||'', aranacak_saat: c.aranacak_saat||'', wants_whatsapp: wantsWhatsapp, satis_talebi: c.satis_talebi===true };
if(isRandevu){ r.arama_durumu='RANDEVU ✅'; r.status_id='UC_ML92HM'; r.bitrix_comment=`AI: Randevu alındı. Tarih: ${r.appointment_date||'özete bakınız'}.`; }
else if(acmadi){ r.arama_durumu='AÇMADI 📵'; r.status_id='UC_5OE5YZ'; r.bitrix_comment='AI: Müşteri aramayı açmadı / meşguldü.'; }
else if(tekrarAra){ r.arama_durumu='TEKRAR ARA 🔁'; r.status_id='UC_04UBVN'; r.bitrix_comment=`AI: Müşteri şu an müsait değil. Aranacak saat: ${r.aranacak_saat||'belirtilmedi'}.`; }
else { r.arama_durumu='OLUMSUZ ❌'; r.status_id='UC_5M177N'; r.bitrix_comment='AI: Görüştü, randevu alınamadı. Lead finest yaşamkent statüsüne ve satışçısına geri bırakıldı.'; }
return [{json:r}];

