// VAPI end-of-call-report -> mevcut Finest Retell-benzeri sonuç formatı
const input = $input.first().json || {};
const raw = input.body || input;
const msg = raw.message || raw;
const call = msg.call || raw.call || {};
const analysis = msg.analysis || call.analysis || raw.analysis || {};
const artifact = msg.artifact || call.artifact || raw.artifact || {};

const eventType = String(msg.type || raw.type || '');
if (eventType !== 'end-of-call-report') {
  return [{json:{...input, body:{event:'vapi_ignored'}, vapi_event_type:eventType}}];
}

function pick(...xs){ for (const x of xs){ if(x!==undefined&&x!==null&&String(x).trim()!=='') return x; } return ''; }
function bool(v){ if(v===true||v===false) return v; return ['true','1','yes','evet'].includes(String(v||'').toLowerCase()); }
function structuredFrom(v){
  if(!v || typeof v!=='object') return {};
  if(v.topraktan_call_result && typeof v.topraktan_call_result==='object') return v.topraktan_call_result;
  const keys=['appointment_date','arama_sonucu','extracted_name','aranacak_saat','satis_talebi','link_istegi','arama_turu','call_summary','call_successful','user_sentiment'];
  if(keys.some(k=>Object.prototype.hasOwnProperty.call(v,k))) return v;
  if(Array.isArray(v)) { for(const x of v){ const r=structuredFrom(x); if(Object.keys(r).length) return r; } }
  for(const x of Object.values(v)){ if(x && typeof x==='object'){ const r=structuredFrom(x); if(Object.keys(r).length) return r; } }
  return {};
}

let structured={};
for(const c of [
  analysis.structuredData,
  analysis.structuredDataMulti,
  msg.structuredOutputs,
  msg.structuredOutput,
  artifact.structuredOutputs,
  artifact.structuredOutput,
  call.structuredOutputs,
  call.structuredOutput
]){
  const r=structuredFrom(c); if(Object.keys(r).length){ structured=r; break; }
}

const vars = call.assistantOverrides?.variableValues || msg.assistantOverrides?.variableValues || {};
const meta = {...(raw.metadata||{}), ...(msg.metadata||{}), ...(call.metadata||{}), ...(vars||{})};
const customer = call.customer || msg.customer || {};
const phoneNumber = call.phoneNumber || msg.phoneNumber || {};

const endedReason = String(pick(call.endedReason, msg.endedReason, call.ended_reason, msg.ended_reason));
const er = endedReason.toLowerCase();
let disc = endedReason;
let callStatus = 'completed';
if(er.includes('no-answer')||er.includes('no_answer')||er.includes('did-not-answer')||er.includes('did-not-pick')){disc='dial_no_answer';callStatus='no_answer';}
else if(er.includes('busy')){disc='dial_busy';callStatus='busy';}
else if(er.includes('voicemail')){disc='voicemail';callStatus='voicemail';}
else if(er.includes('failed')||er.includes('error')||er.includes('provider')||er.includes('telephony')){disc='dial_failed';callStatus='failed';}

const customerPhone=String(pick(customer.number, meta.customer_phone));
const assistantPhone=String(pick(phoneNumber.number, meta.from_number));
const userName=String(pick(meta.user_name, customer.name, structured.extracted_name));
const leadId=String(pick(meta.lead_id, meta.bitrix_id));
const assignedTo=String(pick(meta.assigned_to, meta.lead_owner_id));
const transcript=String(pick(artifact.transcript, msg.transcript, call.transcript));
const summary=String(pick(structured.call_summary, analysis.summary, msg.summary, artifact.summary));

const normalized={
  call_id:String(pick(call.id,msg.callId)),
  call_status:callStatus,
  disconnection_reason:disc,
  from_number:assistantPhone,
  to_number:customerPhone,
  transcript,
  recording_url:String(pick(artifact.recordingUrl, artifact.recording?.url, call.recordingUrl)),
  retell_llm_dynamic_variables:{
    bitrix_id:leadId,
    assigned_to:assignedTo,
    user_name:userName,
    isim:String(pick(meta.isim, userName.split(/\s+/)[0])),
    start_mode:String(pick(meta.start_mode, userName?'confirm_name':'ask_name')),
    customer_phone:customerPhone,
    customer_email:String(pick(meta.customer_email,customer.email)),
    dynamic_greeting:String(pick(meta.dynamic_greeting)),
    bugunun_tarihi:String(pick(meta.bugunun_tarihi)),
    bugun_iso:String(pick(meta.bugun_iso)),
    su_anki_saat:String(pick(meta.su_anki_saat))
  },
  metadata:{...meta,lead_id:leadId,assigned_to:assignedTo,provider:'vapi'},
  call_analysis:{
    custom_analysis_data:{
      appointment_date:String(pick(structured.appointment_date)),
      arama_sonucu:String(pick(structured.arama_sonucu)),
      extracted_name:String(pick(structured.extracted_name,userName)),
      aranacak_saat:String(pick(structured.aranacak_saat)),
      satis_talebi:bool(structured.satis_talebi),
      link_istegi:bool(structured.link_istegi),
      arama_turu:'Giden',
      call_successful:bool(structured.call_successful),
      user_sentiment:String(pick(structured.user_sentiment))
    },
    call_summary:summary,
    call_successful:bool(structured.call_successful),
    user_sentiment:String(pick(structured.user_sentiment))
  }
};

return [{json:{...input, body:{event:'call_analyzed', call:normalized}, vapi_event_type:eventType, vapi_call_id:normalized.call_id}}];
